package cn.zhuatech.projectagent.service;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;class ProjectActionExecutionServiceTest{private final ProjectActionExecutionService s=new ProjectActionExecutionService();@Test void executesGovernedAction(){var r=s.assess(new ProjectActionExecutionService.Request("A1",true,true,true,true,true,true,true,true,true,true,true,true));assertThat(r.decision()).isEqualTo(ProjectActionExecutionService.Decision.EXECUTE);}@Test void coordinatesOperationalGaps(){var r=s.assess(new ProjectActionExecutionService.Request("A2",true,true,true,true,true,true,true,false,false,false,false,true));assertThat(r.actions()).hasSize(2);}@Test void blocksUnauthorizedAction(){var r=s.assess(new ProjectActionExecutionService.Request("A3",false,false,false,false,false,false,false,true,false,true,true,false));assertThat(r.blockers()).hasSize(9);}}
